#pragma once
#include <cstddef>
#include <cstdint>
namespace tab5vault {
constexpr size_t HeaderSize=48,KeyHeaderSize=64,ChunkSize=4096;
constexpr uint32_t Iterations=600000;
struct Stream {virtual ~Stream()=default;virtual size_t read(void*,size_t)=0;virtual size_t write(const void*,size_t)=0;virtual bool seek(size_t)=0;virtual size_t size()=0;};
using Progress=bool(*)(size_t,size_t,void*);
// Entropy is 24 fresh random bytes, generated by the caller for each encryption.
const char* encrypt(Stream& input,Stream& output,const char* password,const uint8_t entropy[24],Progress=nullptr,void* context=nullptr);
// Verifies every chunk before writing any plaintext. Destination must be unpublished.
const char* decrypt(Stream& input,Stream& output,const char* password,Progress=nullptr,void* context=nullptr);
// Version 2: a per-device master key, a public key ID, and fresh 24-byte file entropy.
const char* encryptKey(Stream&,Stream&,const uint8_t key[32],const uint8_t id[16],const uint8_t entropy[24],Progress=nullptr,void* context=nullptr);
const char* decryptKey(Stream&,Stream&,const uint8_t key[32],const uint8_t id[16],Progress=nullptr,void* context=nullptr);
bool keyId(Stream&,uint8_t id[16]);
void wipe(void* data,size_t size);
bool passwordKey(const char* password,const uint8_t salt[16],uint8_t output[32],Progress=nullptr,void* context=nullptr);
}
